"""Generated by tools/gen_stream_codec.py from Configs/schema/stream.json - do not edit.

Teleop wire messages (DESIGN §10). Every message: 12-byte header (magic 'RTGS', version u16, type u16, payload length u32), then the fields in order, little-endian. Arrays and strings are prefixed by a u32 element count (strings: UTF-8 bytes). Poses are in the server's canonical frame: metres, Z-up, +X forward; quaternions w, x, y, z. Regenerate the codecs with tools/gen_stream_codec.py.
"""

from __future__ import annotations

import struct
from dataclasses import dataclass, field

import numpy as np

MAGIC = 0x53475452  # 'RTGS'
VERSION = 1
HEADER = struct.Struct('<IHHI')


class WireError(ValueError):
    pass


def _put(buf: bytearray, kind: str, value) -> None:
    if kind == 'str':
        data = value.encode('utf-8')
        buf += struct.pack('<I', len(data)) + data
    elif kind == 'str[]':
        buf += struct.pack('<I', len(value))
        for s in value:
            _put(buf, 'str', s)
    elif kind.endswith('[]'):
        a = np.ascontiguousarray(np.asarray(value).reshape(-1), dtype=_NP[kind[:-2]])
        buf += struct.pack('<I', a.size) + a.tobytes()
    else:
        buf += struct.pack('<' + _ST[kind], value)


def _get(data: memoryview, at: int, kind: str):
    if kind == 'str':
        (n,) = struct.unpack_from('<I', data, at)
        return bytes(data[at + 4:at + 4 + n]).decode('utf-8'), at + 4 + n
    if kind == 'str[]':
        (n,) = struct.unpack_from('<I', data, at)
        at += 4
        items = []
        for _ in range(n):
            s, at = _get(data, at, 'str')
            items.append(s)
        return items, at
    if kind.endswith('[]'):
        (n,) = struct.unpack_from('<I', data, at)
        dtype = np.dtype(_NP[kind[:-2]])
        end = at + 4 + n * dtype.itemsize
        if end > len(data):
            raise WireError('truncated message')
        return np.frombuffer(data[at + 4:end], dtype=dtype).copy(), end
    fmt = '<' + _ST[kind]
    return struct.unpack_from(fmt, data, at)[0], at + struct.calcsize(fmt)


_ST = {'u8': 'B', 'u16': 'H', 'u32': 'I', 'u64': 'Q', 'i32': 'i', 'f32': 'f', 'f64': 'd'}
_NP = {'u8': '<u1', 'i32': '<i4', 'f32': '<f4', 'f64': '<f8', 'u32': '<u4'}


@dataclass
class StreamStart:
    """Client -> server: opens (or restarts) a stream with its human skeleton."""
    TYPE = 1
    FIELDS = [('stream_id', 'u32'), ('fps', 'f64'), ('skeleton', 'str'), ('joint_names', 'str[]'), ('parents', 'i32[]'), ('rest_offsets', 'f32[]')]
    stream_id: int = 0
    fps: float = 0.0  # nominal input rate (Hz)
    skeleton: str = ''  # e.g. soma77
    joint_names: list = field(default_factory=list)
    parents: np.ndarray = field(default_factory=lambda: np.zeros(0, '<i4'))  # parent joint index, -1 for the root
    rest_offsets: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # J x 3, joint offset from its parent in the rest pose (m)

    def encode(self) -> bytes:
        payload = bytearray()
        for name, kind in self.FIELDS:
            _put(payload, kind, getattr(self, name))
        return HEADER.pack(MAGIC, VERSION, self.TYPE, len(payload)) + bytes(payload)


@dataclass
class HumanFrame:
    """Client -> server: one frame of a stream."""
    TYPE = 2
    FIELDS = [('stream_id', 'u32'), ('seq', 'u64'), ('t_source', 'f64'), ('joint_pos', 'f32[]'), ('joint_quat', 'f32[]')]
    stream_id: int = 0
    seq: int = 0
    t_source: float = 0.0  # capture time of the frame (s, client clock)
    joint_pos: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # J x 3, local joint translations in the parent frame (m; the rest offsets unless the joint moves, e.g. root and hips)
    joint_quat: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # J x 4, local joint rotations relative to the parent

    def encode(self) -> bytes:
        payload = bytearray()
        for name, kind in self.FIELDS:
            _put(payload, kind, getattr(self, name))
        return HEADER.pack(MAGIC, VERSION, self.TYPE, len(payload)) + bytes(payload)


@dataclass
class StreamEnd:
    """Client -> server: closes a stream."""
    TYPE = 3
    FIELDS = [('stream_id', 'u32')]
    stream_id: int = 0

    def encode(self) -> bytes:
        payload = bytearray()
        for name, kind in self.FIELDS:
            _put(payload, kind, getattr(self, name))
        return HEADER.pack(MAGIC, VERSION, self.TYPE, len(payload)) + bytes(payload)


@dataclass
class StreamInfo:
    """Server -> client: reply to StreamStart (status 0) or an error about a stream (status 1)."""
    TYPE = 4
    FIELDS = [('stream_id', 'u32'), ('status', 'u8'), ('message', 'str'), ('robot', 'str'), ('dof_names', 'str[]'), ('contact_groups', 'str[]'), ('lag', 'f64')]
    stream_id: int = 0
    status: int = 0  # 0 ok, 1 error
    message: str = ''
    robot: str = ''
    dof_names: list = field(default_factory=list)
    contact_groups: list = field(default_factory=list)  # names of RobotFrame.contact entries (human contact groups)
    lag: float = 0.0  # output lag behind the newest input (s)

    def encode(self) -> bytes:
        payload = bytearray()
        for name, kind in self.FIELDS:
            _put(payload, kind, getattr(self, name))
        return HEADER.pack(MAGIC, VERSION, self.TYPE, len(payload)) + bytes(payload)


@dataclass
class RobotFrame:
    """Server -> client: the robot pose solved for one HumanFrame."""
    TYPE = 5
    FIELDS = [('stream_id', 'u32'), ('seq', 'u64'), ('t_source', 'f64'), ('t_receive', 'f64'), ('t_emit', 'f64'), ('root_pos', 'f32[]'), ('root_quat', 'f32[]'), ('dof_pos', 'f32[]'), ('dof_vel', 'f32[]'), ('contact', 'u8[]'), ('ground_height', 'f32'), ('cost', 'f32'), ('flags', 'u32')]
    stream_id: int = 0
    seq: int = 0  # of the HumanFrame this solves
    t_source: float = 0.0  # its t_source
    t_receive: float = 0.0  # server clock (s): frame received
    t_emit: float = 0.0  # server clock (s): frame sent
    root_pos: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # 3
    root_quat: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # 4, w x y z
    dof_pos: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # N (rad)
    dof_vel: np.ndarray = field(default_factory=lambda: np.zeros(0, '<f4'))  # N (rad/s), backward difference of the emitted poses
    contact: np.ndarray = field(default_factory=lambda: np.zeros(0, '<u1'))  # per contact group, 1 = in contact
    ground_height: float = 0.0  # tracked ground (m, human frame)
    cost: float = 0.0  # weighted tracking cost of the solve
    flags: int = 0  # bits: 1 velocity clamped, 2 cold start, 4 unsupported, 8 penetration, 16 environment support, 32 flight, 64 frames dropped

    def encode(self) -> bytes:
        payload = bytearray()
        for name, kind in self.FIELDS:
            _put(payload, kind, getattr(self, name))
        return HEADER.pack(MAGIC, VERSION, self.TYPE, len(payload)) + bytes(payload)


MESSAGES = {1: StreamStart, 2: HumanFrame, 3: StreamEnd, 4: StreamInfo, 5: RobotFrame}


def decode(data: bytes):
    """Decodes one message (header + payload) into its dataclass."""
    view = memoryview(data)
    if len(view) < HEADER.size:
        raise WireError('message shorter than its header')
    magic, version, kind, length = HEADER.unpack_from(view, 0)
    if magic != MAGIC or version != VERSION:
        raise WireError(f'bad magic / version {magic:#x} / {version}')
    if HEADER.size + length != len(view):
        raise WireError('length mismatch')
    cls = MESSAGES.get(kind)
    if cls is None:
        raise WireError(f'unknown message type {kind}')
    values, at = {}, HEADER.size
    for name, k in cls.FIELDS:
        values[name], at = _get(view, at, k)
    if at != len(view):
        raise WireError('trailing bytes after the message')
    return cls(**values)
